<script lang="ts">
 import { QrCode, Check, Server, ArrowRight, RotateCcw } from '@lucide/svelte';
 import type { BaselineCopy } from './copy';import type { Locale } from '../data/translations';
 let {c,locale}:{c:BaselineCopy;locale:Locale}=$props();let step=$state(0);let amount=$state<number|undefined>(490);let bank=$state('mono');
 const valid=$derived(amount!==undefined&&Number.isFinite(amount)&&amount>=1&&amount<=1000000);
 const formatted=$derived(new Intl.NumberFormat(locale,{maximumFractionDigits:2}).format(amount??0));
</script>
<section id="demo" class="b-section" data-section="4" aria-labelledby="b-demo-heading"><div class="b-wrap"><p class="b-eyebrow">LIVE SANDBOX</p><h2 id="b-demo-heading" class="b-heading">{c.demoTitle}</h2><p class="b-note">{c.demoDisclaimer}</p><div class="b-demo-workspace b-panel"><div class="b-demo-progress">{#each c.demoSteps as label,i (label)}<div class:b-current={step===i} class:b-done={step>i}><span>{step>i?'✓':`0${i+1}`}</span>{label}</div>{/each}</div><div class="b-demo-grid"><div class="b-demo-screen"><div class="b-product-top"><strong>{c.terminal}</strong><span class="b-demo-label">DEMO</span></div><label class="b-field">{c.amount}<input type="number" min="1" max="1000000" step="0.01" bind:value={amount} disabled={step>0} aria-invalid={!valid}/></label><div class="b-demo-qr" class:b-inactive={step===0} aria-hidden="true"><QrCode size={92}/><span>#1042</span></div><button class="b-button" disabled={!valid||step!==0} onclick={()=>step=1}>{c.create}<ArrowRight size={16}/></button>{#if !valid}<p class="b-error">{c.invalid}</p>{/if}</div><div class="b-demo-screen b-bank-screen"><div class="b-product-top"><strong>{c.demoSteps[1]}</strong><span>↗</span></div><strong class="b-demo-amount">{formatted} ₴</strong><label class="b-field">{c.product.choose}<select bind:value={bank} disabled={step!==1}><option value="mono">monobank</option><option value="pb">PrivatBank</option><option value="pumb">PUMB</option></select></label><p class="b-note">{c.product.bankNote}</p><button class="b-button" disabled={step!==1} onclick={()=>step=2}>{c.confirm}</button></div><div class="b-demo-screen b-server-screen"><Server size={28}/><strong>{c.demoSteps[2]}</strong><div class="b-server-status" aria-live="polite" aria-atomic="true">{#if step===3}<Check class="b-success-check" size={44}/><b>{c.success}</b>{:else}<span class="b-pulse"></span><b>{step===0?c.idle:c.pending}</b>{/if}</div><code>{`invoice: 1042 · status: ${step===3?'paid':step===0?'draft':'pending'}`}</code><button class="b-button b-secondary" disabled={step!==2} onclick={()=>step=3}>{c.verify}</button></div></div><div class="b-demo-bottom"><span class="b-note">{c.mock} · {bank}</span><button class="b-text-button" onclick={()=>step=0}><RotateCcw size={14}/>{c.reset}</button></div></div></div></section>